css:
.naijasim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #3a2417;
    background:
        radial-gradient(circle at 12% -5%, #fff3df 0%, #ffe9c6 38%, #f6d9a8 100%);
    border-radius: 18px;
}

.naijasim-container * {
    box-sizing: border-box;
}

.naijasim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #c0392b 0%, #d35400 48%, #e09f3e 100%);
    color: #fff7ea;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #a9341f;
    box-shadow: 0 12px 30px rgba(120, 50, 20, 0.30);
}

.naijasim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #fffdf6;
    text-shadow: 0 2px 6px rgba(90, 30, 10, 0.35);
}

.naijasim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #fff2d6;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 247, 234, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.naijasim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #fdeacb;
}

.naijasim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b4a2c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.naijasim-period-counter #currentDay,
.naijasim-period-counter #maxPeriods {
    font-weight: 800;
    color: #c0392b;
}

.naijasim-round-name {
    background: rgba(192, 57, 43, 0.12);
    color: #a9341f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.naijasim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a14;
    background: rgba(224, 159, 62, 0.20);
    border: 1px solid rgba(224, 159, 62, 0.45);
    padding: 4px 12px;
    border-radius: 999px;
}

.naijasim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.naijasim-status-card {
    background: linear-gradient(160deg, #fffaf0 0%, #fff1da 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #eccfa3;
    box-shadow: 0 6px 16px rgba(150, 90, 40, 0.14);
    border-top: 4px solid #d35400;
}

.naijasim-card-pen { border-top-color: #1e7d4f; }
.naijasim-card-margin { border-top-color: #2e86c1; }
.naijasim-card-loyalty { border-top-color: #d35400; }
.naijasim-card-bargain { border-top-color: #8e44ad; }

.naijasim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #9a6b3e;
}

.naijasim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3a2417;
    font-variant-numeric: tabular-nums;
}

.naijasim-card-pen .naijasim-value { color: #1e7d4f; }
.naijasim-card-margin .naijasim-value { color: #2e86c1; }
.naijasim-card-loyalty .naijasim-value { color: #d35400; }
.naijasim-card-bargain .naijasim-value { color: #8e44ad; }

.naijasim-sublabel {
    font-size: 0.76rem;
    color: #8a6a48;
    line-height: 1.35;
}

.naijasim-margin-negative .naijasim-value { color: #c0392b; }
.naijasim-margin-positive .naijasim-value { color: #1e7d4f; }

.naijasim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fff6e7;
    border: 1px solid #eccfa3;
    color: #5c3d22;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.naijasim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #1e7d4f;
}

.naijasim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #fffaf0 0%, #fdeccd 100%);
    border-left: 5px solid #d35400;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(150, 90, 40, 0.12);
}

.naijasim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.naijasim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #a9341f;
    margin-bottom: 6px;
}

.naijasim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4f3a26;
}

.naijasim-briefing-text strong { color: #1e7d4f; }
.naijasim-briefing-text em { color: #c0392b; font-style: italic; }

.naijasim-controls {
    background: linear-gradient(160deg, #fffdf8 0%, #fff4e2 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #eccfa3;
    box-shadow: 0 6px 16px rgba(150, 90, 40, 0.12);
}

.naijasim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #a9341f;
    border-bottom: 2px solid #f0d6ad;
    padding-bottom: 8px;
}

.naijasim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5c3d22;
    margin: 14px 0 6px;
}

.naijasim-container select,
.naijasim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d9b988;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #3a2417;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.naijasim-container select:focus,
.naijasim-container input[type="number"]:focus {
    outline: none;
    border-color: #d35400;
    box-shadow: 0 0 0 3px rgba(211, 84, 0, 0.16);
}

.naijasim-container select option {
    background-color: #fffdf8;
    color: #3a2417;
}

.naijasim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #d35400;
}

.naijasim-range-readout,
.naijasim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b4a2c;
    margin-top: 4px;
}

.naijasim-range-readout span:last-child,
.naijasim-alloc-readout span:nth-child(2) {
    color: #d35400;
    font-weight: 800;
}

.naijasim-hint {
    font-size: 0.8rem;
    color: #8a6a48;
    margin-top: 4px;
    line-height: 1.4;
}

.naijasim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.naijasim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fffaf0;
    border: 1px solid #ecd2a6;
    border-radius: 9px;
    padding: 8px 12px;
}

.naijasim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #5c3d22;
}

.naijasim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.naijasim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.naijasim-container .btn-primary {
    background: linear-gradient(135deg, #b8341f 0%, #d35400 55%, #e09f3e 100%);
    border: none;
    color: #fff7ea;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(176, 70, 20, 0.34);
}

.naijasim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.naijasim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d9b988;
    color: #8a5a2c;
    background: transparent;
}

.naijasim-coach {
    background: linear-gradient(160deg, #2c1b10 0%, #3d2415 100%);
    color: #f6e7d2;
    border: 1px solid #5a3a22;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(60, 30, 12, 0.30);
}

.naijasim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e09f3e;
    margin-bottom: 8px;
}

.naijasim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.naijasim-coach-body strong { color: #f3c46b; }
.naijasim-coach-body em { color: #ff9d76; font-style: italic; }

.naijasim-history,
.naijasim-chart {
    background: linear-gradient(160deg, #fffdf8 0%, #fff4e2 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #eccfa3;
    box-shadow: 0 6px 16px rgba(150, 90, 40, 0.12);
}

.naijasim-history h3,
.naijasim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #a9341f;
}

.naijasim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4f3a26;
}

.naijasim-container table#usfHistoryTable th {
    background: #fbe7c6;
    color: #a9341f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e8c693;
}

.naijasim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0dcb9;
    color: #4f3a26;
}

.naijasim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fff7e9;
}

.naijasim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .naijasim-container {
        padding: 14px;
    }
    .naijasim-header h1 {
        font-size: 1.7rem;
    }
    .naijasim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .naijasim-value {
        font-size: 2rem;
    }
    .naijasim-clock {
        margin-left: 0;
    }
    .naijasim-period-counter {
        font-size: 0.88rem;
    }
    .naijasim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .naijasim-alloc-row {
        flex-wrap: wrap;
    }
    .naijasim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .naijasim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, naijasim) ---- */
.naijasim-completion { padding: 8px 4px 4px; }
.naijasim-cm-head { text-align: center; margin-bottom: 16px; }
.naijasim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #b5751d; }
.naijasim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #c79a5a; }
.naijasim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #3a2c17; }
.naijasim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.naijasim-cm-yes { background: rgba(31,122,77,0.14); color: #1a6b43; border: 1px solid rgba(31,122,77,0.5); }
.naijasim-cm-no { background: rgba(181,66,31,0.12); color: #a53f1c; border: 1px solid rgba(181,66,31,0.45); }
.naijasim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.naijasim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(181,117,29,0.08); border: 1px solid rgba(181,117,29,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.naijasim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #b5751d; }
.naijasim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #7a684f; text-transform: uppercase; letter-spacing: 0.03em; }
.naijasim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #3a2c17; }
.naijasim-cm-insights { margin: 0; padding-left: 20px; }
.naijasim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #4a3a25; }

