(function() {
    'use strict';

    class NaijaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Inside the Informal Market`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Greenfield Beverages Nigeria Ltd.).
            this.RTM_BUDGET = 900;        // NGN 900M route-to-market budget
            this.START_PEN = 3;           // <3% informal-channel share
            this.START_MARGIN = 9;        // 9% modern-trade gross margin baseline
            this.MODERN_TRADE_MARGIN = 9; // reference

            // Concept truths (the FACILITATOR DECISION TREE / COMMON ERRORS).
            this.TRUE_BARRIER = `trust`;        // credit + relationship lock-in is the hardest barrier
            this.TRUE_POWER = `gatekeeper`;     // market leaders concentrate power
            this.TRUE_APPROACH = `stacked`;     // margin-stacked with designed-in bargaining room
            this.TRUE_RELATIONSHIP = `sequenced`;
            this.TRUE_RESPONSE = `relationship`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    pen: 3,                  // informal-channel penetration (%)
                    margin: 9,               // Greenfield net margin in the channel (%)
                    loyalty: 20,             // reseller loyalty (0–100)
                    bargain: 25,             // bargain satisfaction (0–100)
                    budgetUsed: 0,           // NGN M of RTM budget committed
                    gatekeeperDependent: false,
                    lostShelf: false,
                    tradeStarved: false,
                    penHistory: [3],
                    marginHistory: [9],
                    loyaltyHistory: [20],
                    bargainHistory: [25],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately modern-trade / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    barrier: `price`,
                    power: `hawker`,
                    unlearn: 40,
                    approach: `fixed`,
                    tradeMargin: 12,
                    bargainRoom: 5,
                    arbitrage: `none`,
                    relationship: `gatekeepers`,
                    credit: `cash`,
                    subdist: 300,
                    van: 200,
                    wholesale: 200,
                    float: 200,
                    shock: `pricecut`,
                    response: `matchprice`,
                    scale: `copy`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ba = document.getElementById(`barrierInput`);
                const po = document.getElementById(`powerInput`);
                const un = document.getElementById(`unlearnInput`);
                if (ba) decisions.barrier = ba.value;
                if (po) decisions.power = po.value;
                if (un) decisions.unlearn = parseInt(un.value, 10);
                if (!Number.isFinite(decisions.unlearn) || decisions.unlearn < 0 || decisions.unlearn > 100) {
                    warn(`warn_unlearn_range`); return false;
                }
            } else if (round === 2) {
                const ap = document.getElementById(`approachInput`);
                const tm = document.getElementById(`tradeMarginInput`);
                const br = document.getElementById(`bargainRoomInput`);
                const ar = document.getElementById(`arbitrageInput`);
                if (ap) decisions.approach = ap.value;
                if (tm) decisions.tradeMargin = parseInt(tm.value, 10);
                if (br) decisions.bargainRoom = parseInt(br.value, 10);
                if (ar) decisions.arbitrage = ar.value;
                if (!Number.isFinite(decisions.tradeMargin) || decisions.tradeMargin < 5 || decisions.tradeMargin > 40) {
                    warn(`warn_trademargin_range`); return false;
                }
                if (!Number.isFinite(decisions.bargainRoom) || decisions.bargainRoom < 0 || decisions.bargainRoom > 30) {
                    warn(`warn_bargainroom_range`); return false;
                }
            } else if (round === 3) {
                const re = document.getElementById(`relationshipInput`);
                const cr = document.getElementById(`creditInput`);
                const sd = document.getElementById(`subdistInput`);
                const vn = document.getElementById(`vanInput`);
                const wh = document.getElementById(`wholesaleInput`);
                const fl = document.getElementById(`floatInput`);
                if (re) decisions.relationship = re.value;
                if (cr) decisions.credit = cr.value;
                if (sd) decisions.subdist = parseFloat(sd.value);
                if (vn) decisions.van = parseFloat(vn.value);
                if (wh) decisions.wholesale = parseFloat(wh.value);
                if (fl) decisions.float = parseFloat(fl.value);
                const parts = [decisions.subdist, decisions.van, decisions.wholesale, decisions.float];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.subdist + decisions.van + decisions.wholesale + decisions.float);
                if (Math.abs(total - this.RTM_BUDGET) > 0.5) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const sh = document.getElementById(`shockInput`);
                const rp = document.getElementById(`responseInput`);
                const sc = document.getElementById(`scaleInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sh) decisions.shock = sh.value;
                if (rp) decisions.response = rp.value;
                if (sc) decisions.scale = sc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let penDelta = 0, marginDelta = 0, loyaltyDelta = 0, bargainDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the channel. Trust/credit lock-in is the real barrier; gatekeepers hold power.
                switch (d.barrier) {
                    case `trust`: loyaltyDelta += 8; bargainDelta += 4; coachKey = `coach_r1_trust`; break;
                    case `distribution`: penDelta += 1; loyaltyDelta += 2; coachKey = `coach_r1_distribution`; break;
                    case `price`: marginDelta -= 1; loyaltyDelta -= 2; coachKey = `coach_r1_price`; break;
                    case `awareness`: loyaltyDelta -= 3; coachKey = `coach_r1_awareness`; break;
                }

                switch (d.power) {
                    case `gatekeeper`: loyaltyDelta += 6; penDelta += 1; if (d.barrier === `trust`) coachKey = `coach_r1_sharp`; break;
                    case `hawker`: loyaltyDelta += 1; break;
                    case `even`: loyaltyDelta -= 2; break;
                    case `distributor`: penDelta -= 1; loyaltyDelta -= 4; coachKey = `coach_r1_distributor`; break;
                }

                // How much of the modern-trade playbook you unlearn shapes everything downstream.
                if (d.unlearn >= 70) { loyaltyDelta += 6; bargainDelta += 6; }
                else if (d.unlearn <= 30) { loyaltyDelta -= 5; bargainDelta -= 4; coachKey = `coach_r1_lowunlearn`; }

                summaryKey = (d.barrier === `trust` && d.power === `gatekeeper`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Pricing for a negotiated channel (Common Errors 1 & 5).
                const tm = d.tradeMargin;     // % of street price left for the chain
                const room = d.bargainRoom;   // designed-in negotiation slack (%)

                switch (d.approach) {
                    case `fixed`:
                        // Common Error 1 — rigid list ignored & arbitraged.
                        loyaltyDelta -= 10; bargainDelta -= 12; penDelta -= 1; coachKey = `coach_r2_fixed`; break;
                    case `tiered`:
                        loyaltyDelta += 4; bargainDelta += 2; penDelta += 1; coachKey = `coach_r2_tiered`; break;
                    case `stacked`:
                        loyaltyDelta += 8; bargainDelta += 6; penDelta += 2; coachKey = `coach_r2_stacked`; break;
                    case `relational`:
                        loyaltyDelta += 6; bargainDelta += 5; coachKey = `coach_r2_relational`; break;
                }

                // Trade margin: too thin starves the trade (Common Error 5); too fat torches Greenfield net margin.
                if (tm < 10) {
                    ds.tradeStarved = true;
                    penDelta -= 2; loyaltyDelta -= 8; marginDelta += 2;
                    if (coachKey === `coach_r2_stacked` || coachKey === `coach_r2_tiered` || coachKey === `coach_r2_relational`) coachKey = `coach_r2_starve`;
                } else if (tm <= 20) {
                    penDelta += 2; loyaltyDelta += 6; marginDelta -= 1;
                } else if (tm <= 28) {
                    penDelta += 2; loyaltyDelta += 4; marginDelta -= 3;
                } else {
                    penDelta += 1; loyaltyDelta += 2; marginDelta -= 6;
                    if (coachKey === `coach_r2_stacked`) coachKey = `coach_r2_givenaway`;
                }

                // Designed-in bargaining room lifts bargain satisfaction but costs a little net margin (Uzo).
                bargainDelta += room * 0.9;
                marginDelta -= room * 0.18;
                if (room === 0 && d.approach !== `fixed`) { bargainDelta -= 6; if (coachKey === `coach_r2_stacked`) coachKey = `coach_r2_noroom`; }

                // Anti-arbitrage guardrail.
                switch (d.arbitrage) {
                    case `zones`: marginDelta += 3; loyaltyDelta += 3; bargainDelta += 1; break;
                    case `rigid`: bargainDelta -= 8; loyaltyDelta -= 4; coachKey = `coach_r2_rigid`; break;
                    case `none`: marginDelta -= 3; loyaltyDelta -= 2; break;
                }

                summaryKey = (d.approach === `stacked` && tm >= 10 && tm <= 28 && room >= 8 && d.arbitrage === `zones`) ? `sum_r2_good` :
                             (d.approach === `fixed` ? `sum_r2_fixed` : `sum_r2_weak`);
            } else if (round === 3) {
                // Relationships, credit & route-to-market allocation (Common Errors 2, 3 & 4).
                switch (d.relationship) {
                    case `sequenced`: loyaltyDelta += 8; penDelta += 2; coachKey = `coach_r3_sequenced`; break;
                    case `broad`: loyaltyDelta += 4; penDelta += 1; break;
                    case `gatekeepers`:
                        ds.gatekeeperDependent = true;
                        loyaltyDelta += 6; penDelta += 3; coachKey = `coach_r3_gatekeepers`; break;
                }

                // Credit policy vs an incumbent that lends 14-day credit (Common Error 2).
                switch (d.credit) {
                    case `cash`:
                        ds.lostShelf = true;
                        penDelta -= 3; loyaltyDelta -= 8; marginDelta += 1; coachKey = `coach_r3_cash`; break;
                    case `selective`:
                        penDelta += 2; loyaltyDelta += 8; marginDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_selective` : coachKey; break;
                    case `aggressive`:
                        penDelta += 3; loyaltyDelta += 4; marginDelta -= 5; coachKey = `coach_r3_aggressive`; break;
                }

                // Route-to-market allocation. Sub-distributors + van sales = purpose-built informal reach.
                // Wholesale partners ride existing distribution; the float must fund the credit policy.
                const reach = d.subdist + d.van;                  // NGN M into purpose-built reach
                penDelta += Math.min(8, reach / 90);              // diminishing returns, capped
                spend = Math.round(d.subdist + d.van + d.wholesale + d.float);

                if (d.van >= 200) penDelta += 1;                  // own routes service tiny low-drop outlets
                if (d.subdist >= 250) loyaltyDelta += 2;          // market insiders as your reach

                // Credit policy needs a float to back it (Common Error 4 coupling: relationship + distribution).
                const needsFloat = (d.credit === `selective` || d.credit === `aggressive`);
                if (needsFloat && d.float < 150) { loyaltyDelta -= 5; coachKey = `coach_r3_underfunded`; }
                if (d.credit === `cash` && d.float >= 250) { penDelta -= 1; }   // float stranded if no credit policy

                summaryKey = (d.relationship === `sequenced` && d.credit !== `cash` && reach >= 450) ? `sum_r3_good` :
                             (d.credit === `cash` ? `sum_r3_cash` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the beachhead & scale (the competitive shock).
                const conv = d.conviction;

                switch (d.response) {
                    case `relationship`:
                        // Hold price, defend on loyalty, service & bargain satisfaction (the right play).
                        loyaltyDelta += 8; bargainDelta += 6; penDelta += 2; marginDelta += 1; coachKey = `coach_r4_relationship`; break;
                    case `matchprice`:
                        // A street price war torches margin and the brand's value.
                        penDelta += 1; marginDelta -= 7; bargainDelta -= 3; coachKey = `coach_r4_matchprice`; break;
                    case `cave`:
                        // Out-bidding / caving surrenders margin and deepens dependence.
                        penDelta += 1; marginDelta -= 6; loyaltyDelta -= 3; coachKey = `coach_r4_cave`;
                        if (ds.gatekeeperDependent) { loyaltyDelta -= 4; coachKey = `coach_r4_squeezed`; }
                        break;
                    case `retreat`:
                        // Abandoning the informal push cedes the mandate.
                        penDelta -= 5; loyaltyDelta -= 8; marginDelta += 3; coachKey = `coach_r4_retreat`; break;
                }

                // The exclusivity squeeze bites hardest if you became gatekeeper-dependent in R3.
                if (d.shock === `exclusivity` && ds.gatekeeperDependent && d.response !== `relationship`) {
                    loyaltyDelta -= 4; penDelta -= 1;
                }

                // Scale path to Onitsha and beyond.
                switch (d.scale) {
                    case `adapt`: penDelta += 3; loyaltyDelta += 3; coachKey = (d.response === `relationship`) ? `coach_r4_holds` : coachKey; break;
                    case `copy`: penDelta += 1; bargainDelta -= 3; break;
                    case `rush`: penDelta += 1; marginDelta -= 3; loyaltyDelta -= 4; coachKey = `coach_r4_rush`; break;
                }

                if (conv >= 65) { loyaltyDelta += 4; marginDelta += 1; }
                else if (conv <= 30) { loyaltyDelta -= 4; marginDelta -= 2; }

                summaryKey = (d.response === `relationship` && d.scale === `adapt`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the NGN 900M RTM budget is committed in Round 3.
            ds.budgetUsed = Math.min(this.RTM_BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas, clamped. Penetration & margin are %, loyalty & bargain are 0–100.
            ds.pen = Math.max(0, Math.min(100, Math.round((ds.pen + penDelta) * 10) / 10));
            ds.margin = Math.max(-5, Math.min(60, Math.round((ds.margin + marginDelta) * 10) / 10));
            ds.loyalty = Math.max(0, Math.min(100, Math.round(ds.loyalty + loyaltyDelta)));
            ds.bargain = Math.max(0, Math.min(100, Math.round(ds.bargain + bargainDelta)));

            ds.penHistory.push(ds.pen);
            ds.marginHistory.push(ds.margin);
            ds.loyaltyHistory.push(ds.loyalty);
            ds.bargainHistory.push(ds.bargain);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                pen: ds.pen,
                penDelta: Math.round(penDelta * 10) / 10,
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                loyalty: ds.loyalty,
                loyaltyDelta: Math.round(loyaltyDelta),
                bargain: ds.bargain,
                bargainDelta: Math.round(bargainDelta),
                budgetUsed: ds.budgetUsed,
                gatekeeperDependent: ds.gatekeeperDependent,
                lostShelf: ds.lostShelf,
                tradeStarved: ds.tradeStarved,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // NGN: English "₦300M" (symbol before); Spanish "300 M₦" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            const num = (abs % 1 === 0) ? String(abs) : abs.toFixed(1);
            if (lang === `es`) {
                return `${sign}${num.replace(`.`, `,`)} M₦`;
            }
            return `${sign}₦${num}M`;
        }

        _fmtPct(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const num = (Math.abs(v) % 1 === 0) ? String(v) : (Math.round(v * 10) / 10).toFixed(1);
            return lang === `es` ? `${String(num).replace(`.`, `,`)}%` : `${num}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`penDisplay`, `domainState.pen`, (v) => self._fmtPct(Number(v)));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.naijasim-card-margin`);
                if (card) {
                    card.classList.toggle(`naijasim-margin-positive`, Number(v) >= 9);
                    card.classList.toggle(`naijasim-margin-negative`, Number(v) < 3);
                }
                return self._fmtPct(Number(v));
            });
            uiManager.bind(`loyaltyDisplay`, `domainState.loyalty`, (v) => Math.round(Number(v)));
            uiManager.bind(`bargainDisplay`, `domainState.bargain`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.RTM_BUDGET);
            });

            // Unlearn slider readout.
            const un = document.getElementById(`unlearnInput`);
            const unReadout = document.getElementById(`unlearnReadout`);
            if (un && unReadout) {
                unReadout.textContent = un.value;
                un.addEventListener(`input`, function() { unReadout.textContent = un.value; });
            }

            // Trade-margin slider readout.
            const tm = document.getElementById(`tradeMarginInput`);
            const tmReadout = document.getElementById(`tradeMarginReadout`);
            if (tm && tmReadout) {
                tmReadout.textContent = tm.value;
                tm.addEventListener(`input`, function() { tmReadout.textContent = tm.value; });
            }

            // Bargaining-room slider readout.
            const br = document.getElementById(`bargainRoomInput`);
            const brReadout = document.getElementById(`bargainRoomReadout`);
            if (br && brReadout) {
                brReadout.textContent = br.value;
                br.addEventListener(`input`, function() { brReadout.textContent = br.value; });
            }

            // RTM-budget live total (must hit NGN 900M).
            const allocIds = [`subdistInput`, `vanInput`, `wholesaleInput`, `floatInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = String(total);
                const bar = document.querySelector(`.naijasim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.RTM_BUDGET) > 0.5) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

