        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.penHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                naijaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.penHistory },
                        { data: ds.loyaltyHistory },
                        { data: ds.bargainHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const pen = Math.round(ds.pen * 10) / 10;
            const margin = Math.round(ds.margin * 10) / 10;
            const loyalty = Math.round(ds.loyalty);
            const bargain = Math.round(ds.bargain);
            const penScore = Math.min(100, pen * 4);
            const marginScore = Math.max(0, Math.min(100, (margin / 18) * 100));
            const composite = Math.round(
                penScore * 0.30 + marginScore * 0.22 + loyalty * 0.26 + bargain * 0.22
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="naijasim-cm-badge naijasim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="naijasim-cm-badge naijasim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.frozenOut) failBadge += ` <span class="naijasim-cm-badge naijasim-cm-no">` + T(`cm_frozen`) + `</span>`;
            if (s.dependent) failBadge += ` <span class="naijasim-cm-badge naijasim-cm-no">` + T(`cm_captured`) + `</span>`;
            if (s.tradeStarved) failBadge += ` <span class="naijasim-cm-badge naijasim-cm-no">` + T(`cm_starved`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="naijasim-cm-metric"><span class="naijasim-cm-mv">` + Number(s.pen || 0).toFixed(1) + `%</span><span class="naijasim-cm-ml">` + T(`cm_m_pen`) + `</span></div>`
                + `<div class="naijasim-cm-metric"><span class="naijasim-cm-mv">` + Number(s.margin || 0).toFixed(1) + `%</span><span class="naijasim-cm-ml">` + T(`cm_m_margin`) + `</span></div>`
                + `<div class="naijasim-cm-metric"><span class="naijasim-cm-mv">` + Math.round(s.loyalty || 0) + `</span><span class="naijasim-cm-ml">` + T(`cm_m_loyalty`) + `</span></div>`
                + `<div class="naijasim-cm-metric"><span class="naijasim-cm-mv">` + Math.round(s.bargain || 0) + `</span><span class="naijasim-cm-ml">` + T(`cm_m_bargain`) + `</span></div>`;
            return ``
                + `<div class="naijasim-completion">`
                +   `<div class="naijasim-cm-head">`
                +     `<div class="naijasim-cm-score">` + score + `<span class="naijasim-cm-score-max">/100</span></div>`
                +     `<div class="naijasim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="naijasim-cm-metrics">` + metrics + `</div>`
                +   `<div class="naijasim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="naijasim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const pen = Math.round(ds.pen * 10) / 10;
            const margin = Math.round(ds.margin * 10) / 10;
            const loyalty = Math.round(ds.loyalty);
            const bargain = Math.round(ds.bargain);

            // Composite: penetration (capped contribution), margin vs the 9% baseline, loyalty, bargain.
            const penScore = Math.min(100, pen * 4);                 // ~25% informal share ≈ a strong beachhead
            const marginScore = Math.max(0, Math.min(100, (margin / 18) * 100)); // 18% ≈ ceiling for full marks
            const composite = this._composite(ds);

            const penetrated = pen >= 10;
            const profitable = margin >= this.MODERN_TRADE_MARGIN;
            const trusted = loyalty >= 60 && bargain >= 55;
            const dependent = ds.gatekeeperDependent && loyalty < 55;
            const frozenOut = ds.lostShelf && loyalty < 45;

            let performanceKey = `grade_frozen`;
            if (penetrated && profitable && trusted && composite >= 75) performanceKey = `grade_secured`;
            else if (penetrated && trusted) performanceKey = `grade_foothold`;
            else if (frozenOut) performanceKey = `grade_shelflost`;
            else if (dependent) performanceKey = `grade_captured`;
            else if (ds.tradeStarved && pen < 8) performanceKey = `grade_starved`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (penetrated && profitable && trusted) insights.push(window.mySimulation.t(`insight_secured`));
            else if (frozenOut) insights.push(window.mySimulation.t(`insight_frozen`));
            else if (dependent) insights.push(window.mySimulation.t(`insight_dependent`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (margin < this.MODERN_TRADE_MARGIN) insights.push(window.mySimulation.t(`insight_margin_low`));
            else if (margin >= 14) insights.push(window.mySimulation.t(`insight_margin_strong`));
            if (ds.tradeStarved) insights.push(window.mySimulation.t(`insight_starved`));
            if (bargain >= 65 && loyalty >= 65) insights.push(window.mySimulation.t(`insight_relational`));
            if (pen >= 12) insights.push(window.mySimulation.t(`insight_scale`));

            return {
                pen: pen,
                margin: margin,
                loyalty: loyalty,
                bargain: bargain,
                penetrated: penetrated,
                profitable: profitable,
                trusted: trusted,
                dependent: dependent,
                frozenOut: frozenOut,
                tradeStarved: ds.tradeStarved,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (penetrated && profitable && trusted && composite >= 75),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.lostShelf && ds.loyalty < 45) return window.mySimulation.t(`hint_cash`);
            if (ds.tradeStarved) return window.mySimulation.t(`hint_starved`);
            if (ds.gatekeeperDependent && state.currentPeriod >= 3 && ds.loyalty < 55) return window.mySimulation.t(`hint_dependent`);
            if (ds.margin < 4 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_margin`);
            if (ds.bargain < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_bargain`);
            if (ds.pen >= 12 && ds.margin >= 9 && ds.loyalty >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

